// Nettoyer et mapper CIQUAL
const items = $input.all();
const output = [];

const nutritionMapping = {
  'Energie, Règlement UE N° 1169 2011 (kcal 100 g)': 'energie_kcal',
  'Protéines, N x facteur de Jones (g 100 g)': 'proteines',
  'Glucides (g 100 g)': 'glucides',
  'Lipides (g 100 g)': 'lipides',
  'Sucres (g 100 g)': 'sucres',
  'Fibres alimentaires (g 100 g)': 'fibres',
  'Eau (g 100 g)': 'eau',
  'AG saturés (g 100 g)': 'ag_satures',
  'AG monoinsaturés (g 100 g)': 'ag_monoinsatures',
  'AG polyinsaturés (g 100 g)': 'ag_polyinsatures',
  'Cholestérol (mg 100 g)': 'cholesterol',
  'Sel chlorure de sodium (g 100 g)': 'sel',
  'Calcium (mg 100 g)': 'calcium',
  'Fer (mg 100 g)': 'fer',
  'Magnésium (mg 100 g)': 'magnesium',
  'Phosphore (mg 100 g)': 'phosphore',
  'Potassium (mg 100 g)': 'potassium',
  'Sodium (mg 100 g)': 'sodium',
  'Zinc (mg 100 g)': 'zinc',
  'Iode (µg 100 g)': 'iode',
  'Sélénium (µg 100 g)': 'selenium',
  'Activité vitaminique A, équivalents rétinol (µg 100 g)': 'vitamine_a',
  'Vitamine C (mg 100 g)': 'vitamine_c',
  'Vitamine D (µg 100 g)': 'vitamine_d',
  'Vitamine E (mg 100 g)': 'vitamine_e',
  'Vitamine K1 (µg 100 g)': 'vitamine_k',
  'Vitamine B1 ou Thiamine (mg 100 g)': 'vitamine_b1',
  'Vitamine B2 ou Riboflavine (mg 100 g)': 'vitamine_b2',
  'Vitamine B3 ou PP ou Niacine (mg 100 g)': 'vitamine_b3',
  'Vitamine B5 ou Acide pantothénique (mg 100 g)': 'vitamine_b5',
  'Vitamine B6 (mg 100 g)': 'vitamine_b6',
  'Vitamine B9 ou Folates totaux (µg 100 g)': 'vitamine_b9',
  'Vitamine B12 (µg 100 g)': 'vitamine_b12'
};

function cleanValue(value) {
  if (!value || value === '-' || value === 'traces' || value === '<' || value === '') return null;
  const num = parseFloat(String(value).replace(',', '.'));
  return isNaN(num) ? null : num;
}

for (const item of items) {
  const json = item.json;

  // FILTRE : Ignorer les lignes sans alim_code
  if (!json.alim_code || json.alim_code === '' || json.alim_code === 'alim_code') {
    continue;
  }

  // Ignorer les lignes sans nom
  if (!json.alim_nom_fr || json.alim_nom_fr === '') {
    continue;
  }

  const cleaned = {
    alim_code: String(json.alim_code).trim(),
    alim_nom_fr: String(json.alim_nom_fr).trim(),
    alim_nom_index: String(json.alim_nom_fr).trim(),
    alim_grp_code: json.alim_grp_code ? String(json.alim_grp_code).trim() : null,
    alim_grp_nom_fr: json.alim_grp_nom_fr ? String(json.alim_grp_nom_fr).trim() : null,
    alim_ssgrp_code: json.alim_ssgrp_code ? String(json.alim_ssgrp_code).trim() : null,
    alim_ssgrp_nom_fr: json.alim_ssgrp_nom_fr ? String(json.alim_ssgrp_nom_fr).trim() : null,
    alim_ssssgrp_code: json.alim_ssssgrp_code ? String(json.alim_ssssgrp_code).trim() : null,
    alim_ssssgrp_nom_fr: json.alim_ssssgrp_nom_fr ? String(json.alim_ssssgrp_nom_fr).trim() : null
  };

  // Mapper les valeurs nutritionnelles
  for (const [oldKey, newKey] of Object.entries(nutritionMapping)) {
    if (json[oldKey] !== undefined) {
      cleaned[newKey] = cleanValue(json[oldKey]);
    }
  }

  output.push({ json: cleaned });
}

return output;

const stats = $input.first().json;

return [{
  json: {
    message: `✅ Import CIQUAL terminé !\n\n📊 Résultats :\n• Total : ${stats.total} aliments\n• Avec calories : ${stats.with_calories}\n• Avec protéines : ${stats.with_proteins}\n\n🎉 Base de données prête !`,
    ...stats
  }
}];
